export type Bindings = { DB:D1Database; BUCKET:R2Bucket; SETUP_TOKEN?:string };
const legacyLabels=['NEW','REFUNDED','back to stock','awaiting customer clarification','INSPECTION REQUIRED','INSTALLED OR USED','REPLACEMENT TO BE SENT','scratched','DAMAGED','Missing Parts','Unknown SKU','Scrapped','empty','Failed Delivery','RE-SEND - DELIVERY'];
export function ukBusinessDate(at=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'}).format(at);}
export async function reserveReturnNumber(db:D1Database,at=new Date()){
 const businessDate=ukBusinessDate(at);
 // Reserve centrally at first receipt. Failed receipts may leave gaps; never reuse numbers.
 const counter=await one(db,"INSERT INTO settings(key,value) VALUES(?, '1') ON CONFLICT(key) DO UPDATE SET value=CAST(CAST(value AS INTEGER)+1 AS TEXT) RETURNING value",'return-sequence:'+businessDate);
 const sequence=Number(counter.value),shortCode='R'+String(sequence).padStart(2,'0')+'N';
 return {businessDate,sequence,shortCode,reference:businessDate.replaceAll('-','')+'-'+shortCode};
}
const roles=['Administrator','Customer service','Warehouse','Inventory','Finance'];
const now=()=>new Date().toISOString(), id=()=>crypto.randomUUID(), encoder=new TextEncoder();
const hex=(b:ArrayBuffer)=>Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('');
const hash=async(s:string)=>hex(await crypto.subtle.digest('SHA-256',encoder.encode(s)));
async function password(p:string,salt=id()){const k=await crypto.subtle.importKey('raw',encoder.encode(p),'PBKDF2',false,['deriveBits']);return salt+':'+hex(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:encoder.encode(salt),iterations:100000},k,256));}
function equal(a:string,b:string){let r=a.length^b.length;for(let i=0;i<Math.max(a.length,b.length);i++)r|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0);return r===0;}
class HttpError extends Error {constructor(public status:number,message:string,public details:any={}){super(message)}}
function check(ok:unknown,message:string,status=400):asserts ok {if(!ok)throw new HttpError(status,message)}
function str(v:unknown,max=1000){return typeof v==='string'?v.trim().slice(0,max):'';}
function cents(v:unknown){check(Number.isSafeInteger(v)&&Number(v)>=0&&Number(v)<=100000000,'Invalid monetary amount.');return Number(v);}
function qty(v:unknown){check(Number.isInteger(v)&&Number(v)>=0&&Number(v)<=10000,'Invalid quantity.');return Number(v);}
function allow(u:any,rs:string[]){check(u.role==='Administrator'||rs.includes(u.role),'Your role cannot perform this action.',403)}
function stmt(db:D1Database,sql:string,...args:any[]){return db.prepare(sql).bind(...args)}
async function one(db:D1Database,sql:string,...args:any[]){return stmt(db,sql,...args).first<any>()}
async function rows(db:D1Database,sql:string,...args:any[]){return (await stmt(db,sql,...args).all<any>()).results}
function publicUser(u:any){return {id:u.id,name:u.name,email:u.email,role:u.role,limit:u.limit,active:u.active}}
function auditSql(db:D1Database,u:any,action:string,detail:any,caseId:string|null=null){return stmt(db,'INSERT INTO audit (id,caseId,actor,action,detail,created) VALUES (?,?,?,?,?,?)',id(),caseId,u.name+' · '+u.email,action,JSON.stringify(detail),now())}
async function config(db:D1Database){const s=await one(db,"SELECT value FROM settings WHERE key='policy'");return {warehouses:['Main warehouse'],slaDays:1,inspectionDays:1,decisionDays:1,separationAbove:20000,requireMfa:false,...(s?JSON.parse(s.value):{})};}
function redact(c:any,u:any){if(u.role==='Warehouse'){delete c.customer;delete c.customerEmail;delete c.paid;delete c.resolution;delete c.refunds;delete c.previousRefunds;delete c.creditNotes;delete c.legacyImport;if(c.timeline)c.timeline=c.timeline.map((event:any)=>({...event,detail:JSON.stringify(stripPrivate(JSON.parse(event.detail)))}));c.items=c.items.map((i:any)=>{const copy={...i};delete copy.paid;return copy});}return c;}
async function readCase(db:D1Database,cid:string,u:any){const r=await one(db,'SELECT * FROM cases WHERE id=?',cid);check(r,'Return not found.',404);const c={...JSON.parse(r.data),version:r.version};c.purchase=JSON.parse((await one(db,'SELECT value FROM settings WHERE key=?','purchase:'+c.orderId))?.value||'null');c.purchaseVersion=c.purchase?JSON.stringify(c.purchase):null;c.photos=await rows(db,'SELECT id,itemId,parcelId,actor,created FROM photos WHERE caseId=? ORDER BY created',cid);c.timeline=await rows(db,'SELECT * FROM audit WHERE caseId=? ORDER BY created DESC',cid);if(u.role==='Warehouse')c.timeline=c.timeline.filter((e:any)=>['Parcel received','Photo added','Inspection submitted','Inspection draft saved','Item identified','Clarification requested','Stock disposition confirmed','Unidentified item split','Evidence linked'].includes(e.action));c.photos=c.photos.map((p:any)=>({...p,links:c.photoLinks?.[p.id]||[]}));c.refunds=await rows(db,'SELECT * FROM refunds WHERE caseId=? ORDER BY created',cid);return redact(c,u);}
